text:
#editContactAddressBookList {
  appearance: none;
  background-color: var(--arrowpanel-dimmed);
  background-image: none;
  border: 1px solid;
  border-color: var(--panel-separator-color) !important;
  box-shadow: none;
  color: inherit;

  &,
  & .menu-icon {
    -moz-context-properties: fill, stroke;
    fill: color-mix(in srgb, currentColor 20%, transparent);
    stroke: currentColor;
  }

  &:not([disabled], [open="true"]):hover {
    background-image: linear-gradient(var(--arrowpanel-dimmed), var(--arrowpanel-dimmed));
    background-color: var(--arrowpanel-dimmed);
  }

  &[open="true"] {
    background-image: linear-gradient(var(--arrowpanel-dimmed-further), var(--arrowpanel-dimmed-further));
    box-shadow: 0 1px 0 hsla(210, 4%, 10%, 0.05) inset;
  }
}
